-- ---------------------------------------------------------------------------
-- POSTFLIGHT: hard guards (any violation → COMMIT below never runs → rollback)
-- ---------------------------------------------------------------------------
do $post013$
declare
  v_rest integer; v_places integer; v_unver integer; v_coords integer;
  v_nolink integer; v_nosrc integer; v_temple integer; v_hotel integer; v_other integer;
begin
  select count(*) into v_rest from public.restaurants where source = 'tptm-master-b13';
  if v_rest <> 17 then
    raise exception 'POSTFLIGHT FAIL: expected 17 batch-013 restaurant rows, found %.', v_rest;
  end if;
  select count(*) into v_places from public.places where source = 'tptm-master-b13';
  if v_places <> 40 then
    raise exception 'POSTFLIGHT FAIL: expected 40 batch-013 place rows, found %.', v_places;
  end if;

  select count(*) into v_unver from public.restaurants where source = 'tptm-master-b13' and verification_status <> 'unverified';
  v_unver := v_unver + (select count(*) from public.places where source = 'tptm-master-b13' and verification_status <> 'unverified');
  if v_unver <> 0 then
    raise exception 'POSTFLIGHT FAIL: % rows are not unverified — an import never self-verifies.', v_unver;
  end if;

  select count(*) into v_coords from public.restaurants where source = 'tptm-master-b13' and (latitude is not null or longitude is not null);
  v_coords := v_coords + (select count(*) from public.places where source = 'tptm-master-b13' and latitude is not null);
  if v_coords <> 1 then
    raise exception 'POSTFLIGHT FAIL: expected exactly 1 evidenced coordinate row, found %.', v_coords;
  end if;

  select count(*) into v_nolink from public.places where source = 'tptm-master-b13' and destination_id is null;
  if v_nolink <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing destination linkage.', v_nolink;
  end if;

  select count(*) into v_nosrc from public.places where source = 'tptm-master-b13' and (source_url is null or source_url = '');
  if v_nosrc <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing source_url.', v_nosrc;
  end if;

  select
    count(*) filter (where place_type = 'temple'),
    count(*) filter (where place_type = 'hotel'),
    count(*) filter (where place_type = 'other')
    into v_temple, v_hotel, v_other
    from public.places where source = 'tptm-master-b13';
  if v_temple <> 9 or v_hotel <> 29 or v_other <> 2 then
    raise exception 'POSTFLIGHT FAIL: place_type distribution drifted (temple=% hotel=% other=%; expected 9/29/2).', v_temple, v_hotel, v_other;
  end if;
  raise notice 'POSTFLIGHT OK: 57 rows verified (17 restaurants + 40 places; temple 9, hotel 29, other 2).';
end
